#!/usr/bin/env python3
"""Qualify the isolated DSB memset repair against original generated bytes."""
from __future__ import annotations

import argparse
import datetime as dt
import json
from pathlib import Path
import subprocess
import time

from setup_datasets import ROOT, GENERATORS, sha256, atomic_json, emit


def metadata_comparison(candidate, reference):
    left, right = candidate.read_text().rstrip("\n").split("|"), reference.read_text().rstrip("\n").split("|")
    return {"candidate_sha256": sha256(candidate), "original_sha256": sha256(reference),
            "version_equal": left[0] == right[0], "candidate_fields": left, "original_fields": right,
            "excluded_from_benchmark_table_byte_equality": True,
            "reason": "dbgen_version records wall-clock creation date/time and invocation paths"}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--candidate-root", type=Path, default=ROOT / ".local/generators/dsb-optimized")
    parser.add_argument("--reuse-sf1-report", type=Path)
    parser.add_argument("--output", type=Path, default=ROOT / "benchmarks/dsb_repaired_build_validation.json")
    args = parser.parse_args()
    source = args.candidate_root.resolve()
    executable = source / "code/tools/dsdgen"
    commit = subprocess.check_output(["git", "-C", str(source), "rev-parse", "HEAD"], text=True).strip()
    if commit != GENERATORS["dsb"][2]:
        raise RuntimeError("Unexpected candidate source revision")
    patch = subprocess.check_output(["git", "-C", str(source), "diff", "--", "code/tools/joint_distribution.c"])
    receipt = ROOT / "benchmarks/dsb_generator_memset.patch"
    if patch != receipt.read_bytes():
        raise RuntimeError("Candidate patch differs from the recorded one-line repair")
    changed = subprocess.check_output(["git", "-C", str(source), "diff", "--name-only"], text=True).splitlines()
    if changed != ["code/tools/joint_distribution.c"]:
        raise RuntimeError(f"Unexpected candidate source changes: {changed}")
    report = {"format_version": 1, "all_passed": False, "eligible_for_published_generation": False,
              "source_url": GENERATORS["dsb"][1], "source_commit": commit,
              "source_unmodified": False, "patch_path": str(receipt.relative_to(ROOT)),
              "patch_sha256": sha256(receipt), "patched_source_sha256": sha256(source / changed[0]),
              "adaptation": "Change the erroneous int-buffer memset length from sizeof(char*) to sizeof(int)",
              "compiler_flags": "-O2 -g -Wall -fcommon", "executable_sha256": sha256(executable),
              "compiler": subprocess.check_output(["gcc", "--version"], text=True).splitlines()[0],
              "qualifications": {}, "started": dt.datetime.now(dt.timezone.utc).isoformat()}
    atomic_json(args.output, report)
    for scale in (1, 10):
        reference = ROOT / (".runtime/data/development/dsb" if scale == 1 else ".runtime/data/published/dsb10")
        original_report = ROOT / ".runtime/datasets/dsb_dev.json"
        tables = sorted(path.stem for path in reference.glob("*.dat") if path.stem != "dbgen_version")
        if len(tables) != 24:
            raise RuntimeError(f"Expected all 24 original DSB benchmark tables at scale {scale}")
        if scale == 10 and not (reference / "generation.json").exists():
            raise RuntimeError("Original SF10 source generation is incomplete")
        reused = None
        if scale == 1 and args.reuse_sf1_report:
            reused = json.loads(args.reuse_sf1_report.read_text())
            if reused["executable_sha256"] != report["executable_sha256"] or sorted(reused["tables"]) != tables:
                raise RuntimeError("The reused SF1 qualification does not describe this exact executable and all tables")
            output = Path(reused["command"][reused["command"].index("-dir") + 1])
        else:
            output = ROOT / f".runtime/data/qualification/dsb-repaired-sf{scale}"
            output.mkdir(parents=True, exist_ok=True)
        started = time.monotonic()
        command = [str(executable), "-scale", str(scale), "-terminate", "N", "-force", "Y", "-dir", str(output), "-rngseed", "0"]
        emit(status="qualification_started", scale=scale, reused=bool(reused), command=command)
        if not reused:
            subprocess.run(command, cwd=source / "code/tools", check=True)
        records = {}
        prior = json.loads(original_report.read_text())["tables"] if scale == 1 else None
        for table in tables:
            actual = sha256(output / f"{table}.dat")
            expected = sha256(reference / f"{table}.dat")
            if prior and prior[table]["source_sha256"] != expected:
                raise RuntimeError(f"Original SF1 file differs from its saved source receipt: {table}")
            records[table] = {"sha256": actual, "original_sha256": expected, "match": actual == expected,
                              "bytes": (output / f"{table}.dat").stat().st_size}
        result = {"all_24_benchmark_tables_byte_identical": all(record["match"] for record in records.values()),
                  "tables": records, "command": command, "reused_prior_run": bool(reused),
                  "elapsed_s": round(time.monotonic() - started, 3),
                  "dbgen_version": metadata_comparison(output / "dbgen_version.dat", reference / "dbgen_version.dat")}
        report["qualifications"][str(scale)] = result
        atomic_json(args.output, report)
        if not result["all_24_benchmark_tables_byte_identical"] or not result["dbgen_version"]["version_equal"]:
            emit(status="qualification_failed", scale=scale, differing=[name for name, value in records.items() if not value["match"]])
            raise RuntimeError("Repaired/optimized generation changes benchmark bytes; retain the original build")
        emit(status="qualification_passed", scale=scale, exact_table_hashes=len(records))
    report["all_passed"] = report["eligible_for_published_generation"] = True
    report["completed"] = dt.datetime.now(dt.timezone.utc).isoformat()
    atomic_json(args.output, report)
    emit(status="candidate_qualified", executable_sha256=report["executable_sha256"])


if __name__ == "__main__":
    main()
